// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementDestroyEventTest extends AbstractEnforcementTest {

    @Test
    public void destroyedContainerNoLongerAllowsItsImage() throws KuraException {
        givenStartedEnforcement();
        givenDigestRegisteredBy(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerWithImageDigest(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenDestroyEventFor(CONTAINER_ID);

        whenStartEventArrivesFor(OTHER_CONTAINER_ID);

        thenContainerWasDeleted(OTHER_CONTAINER_ID);
    }

    @Test
    public void containerRemovedUnderPodmanNoLongerAllowsItsImage() throws KuraException {
        givenStartedEnforcement();
        givenDigestRegisteredBy(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerWithImageDigest(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenPodmanRemoveEventFor(CONTAINER_ID);

        whenStartEventArrivesFor(OTHER_CONTAINER_ID);

        thenContainerWasDeleted(OTHER_CONTAINER_ID);
    }

    @Test
    public void destroyEventIsNotCheckedAgainstTheAllowlist() throws KuraException {
        givenStartedEnforcement();

        whenDestroyEventArrivesFor(CONTAINER_ID);

        thenContainerWasNotDeleted(CONTAINER_ID);
    }

    private void givenDestroyEventFor(String containerId) {
        this.events.publishDestroy(containerId);
        this.scheduler.runPendingTasks();
    }

    private void givenPodmanRemoveEventFor(String containerId) {
        this.events.publishPodmanRemove(containerId);
        this.scheduler.runPendingTasks();
    }

    private void whenDestroyEventArrivesFor(String containerId) {
        this.events.publishDestroy(containerId);
        this.scheduler.runPendingTasks();
    }
}
